        "proof": "\n\n① 放課後子ども教室\n放課後子ども教室は、子どもたちが放課後活動できる居場所を提供し、自由に勉強や\n遊び、スポーツなどの活動等を行っています。日々、自由に参加できるテーマ活動（工\n作、スポーツなど）や 1 年間通して活動をする継続体験（3 年生以上の希望者）があり\nます。これら日頃の活動報告の場として、児童クラブと合同で子どもプラン発表会を開\n催し、作品展、ステージ発表や会運営に 55 人の児童が参加、ステージ発表当日は来場\n者約 133 人の方が観覧し盛大に行われました。その他、夏祭りやハロウィン、焼きい\nも会などの行事も賑わいました。\n・利用時間 平日＝下校～18：00、夏休み＝9：00～16：00\n・登録者数 211 人、延べ利用者数 14,074 人、１日平均 66.7 人/日\n年度別推移\nR4\nR5\nR6\nR7\n登録者数（人）\n195\n188\n188\n211\n１日平均（人/日）\n45.2\n49.5\n58.9\n66.7\n② 児童クラブ\n児童クラブ（学童保育）は、「ふれあい館」を利用し、放課後留守家庭の小学校に通\nっている子どもたちを対象に、平日の放課後のほか、土曜日や夏休みなどの長期休みに\nも対応しています。\n放課後子ども教室とあわせた行事を計画しています。\n・利用時間 平日＝下校～18：30、土曜日＝8：00～18：00、\n長期休み＝8：00～18：30\n・登録者数 151 人、延べ利用者数 13,739 人、１日平均 50.1 人/日\n年度別推移\nR4\nR5\nR6\nR7\n登録者数（人）\n131\n138\n138\n151\n１日平均（人/日）\n36.5\n35.6\n44.8\n50.1\n- 24 -\n\n\n●修繕及び備品等購入\n・ふれあい館東駐車場整地（132 千円）\n・ふれあい館カーテン取替（42 千円）\n・机、デスクマット、事務イス購入（69 千円）\n\n",
        "evaluatedFiscalYear": 2025,
