        "proof": "\n\n○松川村こども計画\nこの計画は、村の子ども・子育て支援に関する総合的な計画で、子ども・子育て\n支援法第61条第１項に基づく「市町村子ども・子育て支援事業計画」、次世代育成\n支援対策推進法第８条に基づく「市町村行動計画」も併せ持ちます。そして、計画\nの一部は、こどもの貧困の解消に向けた対策の推進に関する法律に基づく「市町村\nこどもの貧困の解消に向けた対策についての計画」、子ども・若者育成支援推進法\nに基づく「市町村子ども・若者計画」を包含するものです。\nなお、こども基本法における「こども」とは、心身の発達の過程にある者をいう\nことから、本計画は、乳幼児期（義務教育年齢に達するまで）、学童期（小学生年\n代）及び青年期（中学生年代からおおむね18歳まで）だけでなく、青年期（おおむ\nね18歳以降からおおむね30歳未満まで）、施策によっては、40歳未満までのポスト\n青年期の者を対象とし、こども・若者への支援が特定の年齢によって途切れること\nがないようにします。\n第１期松川村こども計画は令和７年３月に策定し、令和７年度は計画の初年度となり\nます。村では、計画に記載の地域子ども・子育て支援事業として放課後児童健全育成事\n業、利用者支援事業、地域子育て支援拠点事業、妊産婦・乳児健康診査、新生児訪問、\n養育支援事業、一時預かり事業やその他事業として経済的支援を行う学校給食費無償化\n等を実施しています。\n主な事業の実施（利用）状況\n・新生児訪問延べ 41 件\n・子育て世帯訪問支援事業延べ 31 件\n・ペアレントトレーニング全 8 回\n・CAP（子どもへの暴力防止）ワークショップ（小 3、小 5、教職員、保護者対象）\n参加者 202 名\n・一時預かり事業延べ 672 名\n\n- 26 -\n\n\n",
        "evaluatedFiscalYear": 2025,
        "evaluationYear": 2026,
        "note": "Explicit named implemented programme within the bounded actual-year section; parent plan or policy chapter not made a business. Preserve cancelled/partial conditions and no inferred numerical fields."
