        "proofStart": 2942,
        "proof": "\n\n① 小学校の取り組み・支援\n○高学年の算数・英語指導のため、県費教員２名を配置し、算数においては少人数によ\nるコース別学習の充実を図っています。\n○学習充実のため、村費常勤教員３名、非常勤教員５名を加配しています。\n○学年内では授業交換を行ったり、互いに授業を見合ったりして教師のスキルアップに\n努め、担任だけでなく学校全体で子どもの学びを支えています。\n②中学校の取り組み・支援\n○学習充実のため、村費常勤教員１名、非常勤教員２名、支援員２名、ALT１名を加配\nしています。\n○個に応じた学びのあり方について研究するとともに、特別支援学級の生徒を含めた、\nすべての生徒にとって分かりやすい授業の工夫、授業改善について研究をしています。\n○水曜日の放課後に、地域の方に学習ボランティアをお願いし、英語を対象とした放課\n後学習教室を開設しました。3 年生の希望者 14 名を対象に 5 月～10 月に 14 回実施し\nました。また、8 月から 3 月までの水曜日夜間を主に、深く学習したいと考える意欲\nのある生徒の学びの場として「ステップアップ学習教室 ～もっと勉強やり隊～」を\n実施し、１・２年生の希望者が受講しました。\n③学力向上のための支援、連携\n○学校と定期の懇談会や学校訪問を実施し、学校運営や学力向上などについて意見交換、\n指導・助言を行っています。\n○全国学力状況調査の結果を全職員で分析して、授業や学級経営でどのように生かして\nいくかを具体的な取り組みを出し合い、それぞれの立場で実践しています。\n\n-3-\n\n\n",
