        "proofStart": 18604,
        "proof": "\n\n① 放課後子ども教室\n放課後子ども教室は、子どもたちが放課後活動できる居場所を提供し、自由に勉強や\n遊び、スポーツなどの活動等を行っています。日々、自由に参加できるテーマ活動（工\n作、スポーツなど）や 1 年間通して活動をする継続体験（3 年生以上の希望者）があり\nます。これら日頃の活動報告の場として、児童クラブと合同で子どもプラン発表会を開\n催し、発表や会運営に 45 名の児童が参加、来場者約 170 名の方が観覧し盛大に行われ\nました。その他、夏祭りやハロウィン、焼きいも会などの行事も賑わいました。\n・利用時間 平日＝下校～18：00、夏休み＝9：00～16：00\n・登録者数 188 人、延べ利用者数 12,542 人、１日平均 58.9 人/日\n年度別推移\nR3\nR4\nR5\nR6\n登録者数（人）\n201\n195\n188\n188\n１日平均（人/日）\n55.1\n45.2\n49.5\n58.9\n② 児童クラブ\n児童クラブ（学童保育）は、「ふれあい館」を利用し、放課後留守家庭の小学校に通\nっている子どもたちを対象に、平日の放課後のほか、土曜日や夏休みなどの長期休みに\nも対応しています。\n放課後子ども教室とあわせた行事を計画しています。\n・利用時間 平日＝下校～18：30、土曜日＝8：00～18：00、\n長期休み＝8：00～18：30\n・登録者数 138 人、延べ利用者数 12,235 人、１日平均 44.8 人/日\n年度別推移\nR3\nR4\nR5\nR6\n登録者数（人）\n120\n131\n138\n138\n１日平均（人/日）\n36.8\n36.5\n35.6\n44.8\n\n- 24 -\n\n\n●修繕及び備品等購入\n・ふれあい館事務室エアコン交換（186 千円）\n・ふれあい館フェンス増設（108 千円）\n・児童クラブ用かき氷機購入（147 千円）\n\n",
