        "proofStart": 19663,
        "proof": "\n\n○松川村子ども・子育て支援事業計画\nこの計画は、子ども・子育て支援法に規定する「市町村子ども・子育て支援事業計画」\nにあたる法定計画であり、５年を一期とする教育・保育及び地域子ども・子育て支援事\n業の提供体制の確保・業務の円滑な実施に関する計画並びに次世代育成支援対策推進法\nに基づく市町村行動計画として位置付けています。母子保健の視点からも必要と考える\n具体的な事業についても、計画全体に組み入れています。\n第２期松川村子ども・子育て支援事業計画は令和２年３月に策定し、令和６年度は第\n２期計画の最終年度となります。村では、事業計画に記載の地域子ども・子育て支援事\n業として放課後児童健全育成事業、利用者支援事業、地域子育て支援拠点事業、妊産婦・\n乳児健康診査、新生児訪問、養育支援事業、一時預かり事業やその他事業として経済的\n支援を行う学校給食費助成事業等を実施しています。\n主な事業の実施（利用）状況\n・新生児訪問延べ 54 件\n・子育て世帯訪問支援事業延べ 65 件\n・ペアレントトレーニング全 8 回\n・一時預かり事業延べ 595 人\n・学校給食費助成（令和６年７月より無償化）\n松川小学校 １人年額 61,740 円（総額 26,730,800 円）\n松川中学校 １人年額 70,020 円（総額 15,657,650 円）\n\n- 26 -\n\n\n",
