        "proofStart": 17652,
        "proof": "\n\n① 放課後子ども教室\n放課後子ども教室は、子どもたちが放課後活動できる居場所を提供し、自由に勉強や\n遊び、スポーツなどの活動等を行っています。日々、自由に参加できるテーマ活動（工\n作、スポーツなど）や 1 年間通して活動をする継続体験（3 年生以上の希望者）があり\nます。これら日頃の活動報告の場として、児童クラブと合同で子どもプラン発表会を 4\n年ぶり（コロナ禍縮小版からは 2 年ぶり）に開催し、約 200 名の方が参観し盛大に行\nわれました。その他、夏祭りやハロウィンなどの行事も賑わいました。\n・利用時間 平日＝下校～18：00、夏休み＝9：00～16：00\n・登録者数 188 人、延べ利用者数 10,486 人、１日平均 49.5 人/日\n年度別推移\nR2\nR3\nR4\nR5\n登録者数（人）\n207\n201\n195\n188\n１日平均（人/日）\n53.7\n55.1\n45.2\n49.5\n② 児童クラブ\n児童クラブ（学童保育）は、「ふれあい館」を利用し、放課後留守家庭の小学校に通\nっている子どもたちを対象に、平日の放課後のほか、土曜日や夏休みなどの長期休みに\nも対応しています。\n放課後子ども教室とあわせた行事を計画しています。\n・利用時間 平日＝下校～18：30、土曜日＝8：00～18：00、\n長期休み＝8：00～18：30\n・登録者数 138 人、延べ利用者数 9,755 人、１日平均 35.6 人/日\n年度別推移\nR2\nR3\nR4\nR5\n登録者数（人）\n137\n120\n131\n138\n１日平均（人/日）\n26.8\n36.8\n36.5\n35.6\n\n- 22 -\n\n\n●修繕及び備品等購入\n・ふれあい館図書室エアコン取替工事（299 千円）\n・ふれあい館図書室ＦＦ式石油暖房機取替工事（193 千円）\n・ふれあい館事務室温水器取替工事（167 千円）\n・ふれあい館自動水栓交換工事（57 千円）\n\n",
        "evaluatedFiscalYear": 2023,
        "evaluationYear": 2024,
        "note": "Explicit named implemented programme within the bounded actual-year section; parent plan or policy chapter not made a business. Preserve cancelled/partial conditions and no inferred numerical fields."
